use std::collections::HashMap;
use std::io::{self, Write};
use std::process::ExitCode;

/// Running total for a key; `None` once the sum has left the i64 range.
type Total = Option<i64>;

fn lines(data: &[u8]) -> Vec<&[u8]> {
    let mut out: Vec<&[u8]> = data.split(|&b| b == b'\n').collect();
    // A trailing newline terminates the last line rather than starting a new one.
    if out.last().is_some_and(|l| l.is_empty()) {
        out.pop();
    }
    out.into_iter()
        .map(|l| l.strip_suffix(b"\r").unwrap_or(l))
        .collect()
}

fn parse_value(bytes: &[u8]) -> Option<i64> {
    std::str::from_utf8(bytes).ok()?.trim().parse().ok()
}

fn run(data: &[u8], out: &mut impl Write) -> io::Result<()> {
    let all = lines(data);
    let sep = all.iter().position(|l| l.is_empty()).unwrap_or(all.len());
    let (records, queries) = all.split_at(sep);
    let queries = queries.get(1..).unwrap_or(&[]);

    let mut totals: HashMap<&[u8], Total> = HashMap::new();
    for rec in records {
        let Some(split) = rec.iter().position(|&b| b == b' ') else {
            continue;
        };
        let (key, rest) = (&rec[..split], &rec[split + 1..]);
        let Some(value) = parse_value(rest) else {
            continue;
        };
        let entry = totals.entry(key).or_insert(Some(0));
        *entry = entry.and_then(|t| t.checked_add(value));
    }

    for &key in queries {
        if key.is_empty() {
            continue;
        }
        out.write_all(key)?;
        out.write_all(b"=")?;
        match totals.get(key) {
            None => out.write_all(b"absent")?,
            Some(None) => out.write_all(b"overflow")?,
            Some(Some(t)) => write!(out, "{t}")?,
        }
        out.write_all(b"\n")?;
    }
    out.flush()
}

fn main() -> ExitCode {
    let Some(path) = std::env::args_os().nth(1) else {
        eprintln!("usage: keyed_totals <file>");
        return ExitCode::from(2);
    };
    let data = match std::fs::read(&path) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("cannot read {}: {e}", path.to_string_lossy());
            return ExitCode::from(1);
        }
    };
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    match run(&data, &mut out) {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) if e.kind() == io::ErrorKind::BrokenPipe => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("write error: {e}");
            ExitCode::from(1)
        }
    }
}
